path='scripts/browser-smoke.mjs'; p=Path(path); text=p.read_text(encoding='utf-8'); anchor='  const malformed=await malformedChecks(page);'
if text.count(anchor)!=1: raise SystemExit('browser smoke anchor missing')
block=r'''  const openingBalance=await evaluate(page,`(()=>{
    const selected=state.selectedDifficulty;state.selectedDifficulty='normal';
    resetGame();state.time=170;state.spawnTimer=9999;state.encounterTimer=9999;state.entities.enemies.length=0;state.bossBags={boss:['eclipse']};state.bossIndex=0;const first=spawnEnemy('boss'),firstStats={firstBoss:first.firstBoss,hp:first.maxHp,damage:first.damage,speed:first.speed,skill:first.skillCd,burst:first.burstCd,pulse:first.pulseCd};
    state.entities.enemies.length=0;state.bossBags={boss:['eclipse']};state.bossIndex=1;const later=spawnEnemy('boss'),laterStats={firstBoss:later.firstBoss,hp:later.maxHp,damage:later.damage,speed:later.speed,skill:later.skillCd,burst:later.burstCd,pulse:later.pulseCd};
    state.entities.enemies.length=0;const chance60=stackfallRangedSpawnChance(60),chance170=stackfallRangedSpawnChance(170),chance600=stackfallRangedSpawnChance(600);state.entities.enemies.push({id:state.nextId++,type:'boss',kind:'boss',firstBoss:true,dead:false,x:900,y:0,r:50,hp:1,maxHp:1,speed:0,damage:0});const duringFirst=stackfallRangedSpawnChance(170);for(let i=0;i<2;i++)state.entities.enemies.push({id:state.nextId++,type:'ranged',kind:'normal',dead:false,x:500+i*20,y:0,r:12,hp:1,maxHp:1,speed:0,damage:0});const capped=stackfallRangedSpawnChance(170);
    resetGame();state.spawnTimer=9999;state.encounterTimer=9999;state.entities.enemies.length=0;state.entities.projectiles.length=0;state.entities.curves.length=0;state.passives.multiplicity=2;state.weaponStacks.core=1;state.weaponStacks.arc=1;const targets=[];for(let i=0;i<5;i++){const a=-.7+i*.35,e={id:state.nextId++,type:'grunt',kind:'normal',x:220+Math.cos(a)*90,y:Math.sin(a)*190,r:12,hp:1000,maxHp:1000,speed:0,damage:0,color:'#fff',xp:0,hit:0,dead:false,phase:0,skillCd:999,burstCd:999,pulseCd:999};state.entities.enemies.push(e);targets.push(e);}rebuildEnemyIndex();spawnCoreShot(targets[0],false);fireBoomerang(targets[0],1,false);updatePendingActions(1);const coreTargets=state.entities.projectiles.filter(p=>p.source==='core-multiplicity').map(p=>p.multiplicityTargetId),arcTargets=state.entities.curves.filter(c=>c.ricochet).map(c=>c.targetId);state.selectedDifficulty=selected;resetGame();return{firstStats,laterStats,chance60,chance170,chance600,duringFirst,capped,coreTargets,arcTargets};
  })()`);scenario.observations.openingBalance=openingBalance;check(openingBalance.firstStats.firstBoss===true&&openingBalance.laterStats.firstBoss===false,'first boss marker is invalid',page.name);check(openingBalance.firstStats.hp<openingBalance.laterStats.hp*.82&&openingBalance.firstStats.damage<openingBalance.laterStats.damage*.78&&openingBalance.firstStats.speed<openingBalance.laterStats.speed,'first boss relief did not apply',page.name);check(openingBalance.chance60===0&&openingBalance.chance170<.095&&openingBalance.chance600>openingBalance.chance170&&openingBalance.duringFirst<openingBalance.chance170&&openingBalance.capped===0,'early ranged suppression is invalid',page.name);check(openingBalance.coreTargets.length===2&&openingBalance.coreTargets.every(Boolean)&&new Set(openingBalance.coreTargets).size===2&&openingBalance.arcTargets.length===2&&new Set(openingBalance.arcTargets).size===2,`multiplicity targets were not separated: ${JSON.stringify(openingBalance)}`,page.name);

'''
p.write_text(text.replace(anchor,block+anchor,1),encoding='utf-8')
